package com.huan.capture.sr.webrtc.capture;import android.content.Context;import org.webrtc.FileVideoCapturer;import java.io.File;import java.io.IOException;/** * <br> * * <br> */public class LocalYuvVideoCaptureAdapter extends VideoCaptureAdapter {    public LocalYuvVideoCaptureAdapter(Context context) {        try {            mVideoCapture = new FileVideoCapturer(new File(context.getCacheDir(), "ducks_take_off_420_720p50.y4m").getAbsolutePath());        } catch (IOException e) {            e.printStackTrace();        }    }}